// Copies the translations of the labels this app uses from the web's dictionaries (apps/web/lib/i18n/*.json)
// into src/core/i18n.generated.ts, so the phone ships only its own labels. Run after `npm run i18n:translate`
// on the web: `npm run sync:i18n`. `--check` exits non-zero when the generated file is out of date.
import { readFile, readdir, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { appKeys } from './i18n-keys.mjs';

const webI18n = new URL('../../web/lib/i18n/', import.meta.url);
const target = new URL('../src/core/i18n.generated.ts', import.meta.url);

export async function generated() {
  const used = await appKeys();
  const english = JSON.parse(await readFile(new URL('en.json', webI18n), 'utf8'));
  // en.json order keeps the file stable as labels are added.
  const keys = Object.keys(english).filter((text) => used.has(text));
  const files = (await readdir(webI18n)).filter((name) => name.endsWith('.json') && name !== 'en.json').sort();
  const dictionaries = {};
  for (const file of files) {
    const dictionary = JSON.parse(await readFile(new URL(file, webI18n), 'utf8'));
    dictionaries[file.replace('.json', '')] = Object.fromEntries(keys.filter((text) => dictionary[text]).map((text) => [text, dictionary[text]]));
  }
  return [
    '// Generated by `npm run sync:i18n` from apps/web/lib/i18n: the translations of the labels this app uses. Do not edit.',
    `export const dictionaries: Record<string, Record<string, string>> = ${JSON.stringify(dictionaries, null, 2)};`,
    '',
  ].join('\n');
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const next = await generated();
  const current = await readFile(target, 'utf8').catch(() => '');
  if (process.argv.includes('--check')) {
    if (current !== next) { console.error('src/core/i18n.generated.ts is out of date: run npm run sync:i18n'); process.exit(1); }
    console.log('i18n.generated.ts is up to date');
  } else {
    if (current !== next) await writeFile(target, next);
    const sizes = Object.entries(JSON.parse(next.slice(next.indexOf('{'), next.lastIndexOf(';')))).map(([id, entries]) => `${id} ${Object.keys(entries).length}`);
    console.log(`i18n.generated.ts: ${sizes.join(', ')}`);
  }
}
